	{"char":"Ɵ","name":"带横杠的O","intro":"⚠️Unicode 在 NamesList 自注：“the formal name does not describe the glyph”（正式名不描述字形）。名字里的 middle tilde（中部波浪号）是沿用的旧术语，实际字形是 O 中间一道横杠，没有波浪号。改名受 Name Stability 政策限制，改不了。直译名照搬官方名，只作搜索用。"},
	{"char":"ɿ","name":"舌尖前元音","intro":"⚠️Unicode 在 NamesList 自注：“this character is not actually a reversed 027E”。官方码表 U0250.pdf 写明：这个符号和 U+0285 都是从瑞典 Landsmålsalfabetet 的斜体无点长 i 借来的，被 Karlgren 用于汉学记音后各自独立成字；名说“反形 R”是误导。记音值等于 IPA 的 z̩（z＋下加竖线），即普通话「资/思」的韵母。直译名照搬官方名，只作搜索用。"},
	{"char":"ʅ","name":"舌尖后元音","intro":"⚠️Unicode 在 NamesList 自注：“this character is not actually a reversed esh”。官方码表 U0250.pdf 写明：它那条“尾巴”本是斜体长 i 的钩状收笔，因用于舌尖后元音才被重新解读为卷舌钩；与 ʃ 无字源关系。记音值等于 IPA 的 ʐ̩（ʐ＋下加竖线），即普通话「知/诗」的韵母。直译名照搬官方名，只作搜索用。"},
	{"char":"Ѽ","name":"教会斯拉夫宽ω","intro":"⚠️Unicode 在 NamesList 自注：“despite its name, this character does not have a titlo, nor is it composed of an omega plus a diacritic”。名字说它是 ω 加 titlo 缩写符拼成，实际既没有 titlo、也不是 ω 加变音符的组合。直译名照搬官方名，只作搜索用。"},
	{"char":"⺕","name":"手部·又形","intro":"⚠️Unicode 在 NamesList 自注：它其实是“手”部的一种写法（a form of the radical for hand），只因字形与“嘴”部（snout）相似才得了这个名字。直译名照搬官方名，只作搜索用。"},
	{"char":"⺜","name":"帽部·冃形","intro":"⚠️Unicode 在 NamesList 自注：它其实是“帽”部（hat）的一种写法，只因字形与“日”部相似才得了这个名字。直译名照搬官方名，只作搜索用。"},
	{"char":"׆","name":"希伯来抄写标记","intro":"⚠️Unicode 在 NamesList 自注：“does not historically derive from the letter nun”。名字里的 nun（נ）是后人附会，历史上与字母 nun 无关。直译名照搬官方名，只作搜索用。"},
	{"char":"ٰ","name":"阿拉伯上标元音符","intro":"⚠️Unicode 在 NamesList 自注：“actually a vowel sign, despite the name”。名字说它是“字母”，实际是元音符（作长音符用的上标 alif）。直译名照搬官方名，只作搜索用。"},
	{"char":"ລ","name":"老挝字母LO","intro":"⚠️Unicode 在 NamesList 自注：“name is a mistake, lo loot is the mnemonic for 0EA3”——两个老挝字母的名字互换了。Unicode 已给出正式更正名 LAO LETTER LO（类型 correction）。直译名照搬官方名，只作搜索用。"},
	{"char":"་","name":"藏文音节点TSHEG","intro":"⚠️Unicode 在 NamesList 自注：“character name is a misnomer”。tsheg 并不限于音节之间（intersyllabic），名字把用法说窄了。直译名照搬官方名，只作搜索用。"},
	{"char":"〞","name":"闭式双撇引号","intro":"⚠️Unicode 在 NamesList 自注：“this is a mistaken analogue to 201D; 301F is preferred”。它是照 U+201D 类推造出来的错误类比字，该用 U+301F。直译名照搬官方名，只作搜索用。"},
	{"char":"𒌦","intro":"⚠️Unicode 在 NamesList 自注：“the names of this and the following sign incorrectly reflect the gunû relationship between them”。它和 U+12327 的 gunû 派生关系记反了——U+12327 才是基准，UN 是它的 gunû 形；U+12327 的正式更正名为 CUNEIFORM SIGN KALAM（类型 correction）。直译名照搬官方名，只作搜索用。"},
	{"char":"𞢙","name":"门德音节M172 MBO","intro":"⚠️Unicode 在 NamesList 自注：“this and the following character had swapped transliterations of the vowels in their names”。它跟 U+1E89A 名字里的元音转写互换了，Unicode 已给出正式更正名 MENDE KIKAKUI SYLLABLE M172 MBO（类型 correction）。直译名照搬官方名，只作搜索用。"},
	{"char":"🯄","intro":"⚠️Unicode 在 NamesList 自注：“glyph does not necessarily extend to the edges of the character cell”。名字说“方框内”（squared），但字形不必铺满整个字格。直译名照搬官方名，只作搜索用。"},
	{"char":"✟","intro":"拉丁十字的描边款。"}
